pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the calldata bytes used to call version() via low-level call
    function testFuzz_property(bytes memory callData) public {
        // keep calldata reasonably small to avoid out-of-gas in fuzz harness
        vm.assume(callData.length <= 200);

        // Prepare low-level call to c with the provided calldata.
        // We require that when the call succeeds, it returns the ABI-encoded string "1.0.0".
        (bool success, bytes memory ret) = address(c).call(callData);

        // If the call succeeded, decode the returned bytes as a string if possible.
        // We check that any successful return equals abi.encode(string("1.0.0")).
        if (success) {
            // Single assertion reading c's behavior: the returned data must equal the expected encoding.
            assertTrue(keccak256(ret) == keccak256(abi.encode(string("1.0.0"))));
        } else {
            // If call reverts, the reference contract never reverts for any calldata (its version() is pure),
            // but some malformed calldata may target non-existent function selectors and result in success with empty return
            // (which is still considered success). Reverts are not expected for reference; therefore we assert false
            // only when the reference would revert. To be safe and keep property universal, we accept reverted calls
            // by not asserting anything in that branch. Thus the only assertion is above for successful calls.
        }
    }
}

