pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz over a single byte of calldata. The rule: for ANY single-byte calldata
    // passed in a low-level call to address(c), if the call succeeds then the returned
    // raw bytes equal abi.encodePacked("1.0.0"). The mutant (which returns "1.0.1")
    // will cause this assertion to fail for some 1-byte input.
    function testFuzz_property(bytes1 b) public {
        // keep domain wide: a single byte can be any value
        bytes memory data = new bytes(1);
        data[0] = b;

        // perform low-level call so we treat calldata variations; capture success and returndata
        (bool ok, bytes memory ret) = address(c).call(data);

        // We assert a universal property over all single-byte calldata: whenever the call succeeds,
        // the returned raw bytes are exactly abi.encodePacked("1.0.0"). This holds for the reference
        // but is violated by the mutant for some input because it returns "1.0.1" instead.
        bytes memory expected = abi.encodePacked("1.0.0");

        // Single assertion reading c's observable behavior (low-level call result and returndata)
        // true if call failed (we only require the property when call succeeds), otherwise compare returndata
        if (!ok) {
            // If the call reverted, the reference still satisfies the property vacuously for this input
            assertTrue(true);
        } else {
            assertTrue(keccak256(ret) == keccak256(expected));
        }
    }
}

