import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to ensure we don't hard-code any specific actor
    function testFuzz_property(address caller) public {
        // wide admissible domain: exclude zero address because some runtimes may treat it specially
        vm.assume(caller != address(0));

        // Call version() from an arbitrary caller; it's an external pure function so caller shouldn't matter
        bool ok;
        string memory v;
        try c.version() returns (string memory s) {
            ok = true;
