pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz a dummy uint256 so the fuzzer can explore calling version() under many inputs
    function testFuzz_property(uint256 dummy) public {
        // Keep the domain wide; no restrictive assume needed. Use dummy so fuzzer runs many cases.

        // call version and capture whether it returns exactly "1.0.0"
        bool ok;
        try c.version() returns (string memory v) {
            // compare returned string to expected canonical value
            // convert to bytes for equality check
            bytes memory rb = bytes(v);
            bytes memory expect = bytes("1.0.0");
            if (rb.length == expect.length) {
                bool eq = true;
                for (uint i = 0; i < rb.length; i++) {
                    if (rb[i] != expect[i]) { eq = false; break; }
                }
                ok = eq;
            } else {
                ok = false;
            }
        } catch {
            // If call reverts (it shouldn't), mark as not ok
            ok = false;
        }

        // The reference contract always satisfies ok == true for all inputs; the mutant will produce ok == false for some input (the fuzzer will find it)
        assertTrue(ok);
    }
}

