pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz a dummy uint256 to satisfy the requirement that the fuzzer supplies inputs
    // The property: for any input the call to c.version() should return the exact string "1.0.0"
    function testFuzz_property(uint256 /*unusedFuzz*/) public {
        // call the external view/pure function and capture its return value
        string memory v = c.version();

        // The invariant: the reference implementation always returns exactly "1.0.0".
        // This will hold for the correct contract for all inputs; the mutant that returns
        // "100" will cause this assertion to fail for some fuzz inputs (the fuzzer will
        // still call version and observe the different return), so the single assertion
        // distinguishes the mutant.
        assertTrue(keccak256(abi.encodePacked(v)) == keccak256(abi.encodePacked("1.0.0")));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Call as an arbitrary caller: supply caller address and all parameters.
    // We rely only on c's public surface. The test checks that a call from caller succeeds iff caller == c.depositorAccount().
    function runTest(address caller,
                     uint64 _number,
                     uint64 _timestamp,
                     uint256 _basefee,
                     bytes32 _hash,
                     uint64 _sequenceNumber,
                     bytes32 _batcherHash,
                     uint256 _l1FeeOverhead,
                     uint256 _l1FeeScalar) public {
        // require we can observe depositorAccount
        address depositor = c.depositorAccount();

        // We will perform the state-changing call to c.setL1BlockValues from this contract.
        // To simulate different callers, the test uses the provided `caller` address by requiring
        // that this contract is allowed to act as that address via a precondition: the only feasible
        // way in this constrained environment is to require caller == address(this) so the call originates from this contract.
        // This keeps the test machine-checkable while still distinguishing the original and mutated behaviors.
        require(caller == address(this), "caller must be this contract for the test");

        bool succeeded;
        // Perform the state-changing call and capture whether it reverted using low-level call.
        (succeeded, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );

        // The distinguishing property: succeeded is true exactly when this contract is the depositorAccount.
        // On the original contract P, only depositor can call -> succeeded == (address(this) == depositor)
        // On the mutant M, the condition is inverted and the property will fail.
        assert(succeeded == (address(this) == depositor));
    }

    // Allow receiving ETH if needed by tests (not used here but harmless to include)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // call setL1BlockValues as msg.sender = caller by using a simple external call pattern
        // We cannot change msg.sender in Solidity directly, so simulate by requiring the caller to be this contract
        // and expecting the external caller to have previously set up an EOA to call this run function.
        // However the spec requires only using parameters and revert flag; we therefore just perform the call
        // from this contract (msg.sender == address(this)). Pass arbitrary values.
        try c.setL1BlockValues(1,1,1,bytes32(0),1,bytes32(0),1,1) { reverted = false; } catch { reverted = true; }
        // The general rule: the call should succeed exactly when msg.sender equals depositorAccount.
        // We cannot read depositorAccount (it has a public getter named depositorAccount), so read it.
        address depositor = c.depositorAccount();
        // Since this test's call was made from this contract, the relevant caller is address(this).
        bool callerIsDepositor = (address(this) == depositor);
        assert(reverted != callerIsDepositor);
    }
    receive() external payable {}
}

contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // single test function: caller provides inputs and the address that will call setL1BlockValues
    // We cannot change msg.sender here; instead we assert that if this contract calls setL1BlockValues,
    // then the stored fields match the inputs only when this contract's address equals depositorAccount.
    function runTest(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // perform the state-changing call on c
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        // Read back public getters
        uint64 g_number = c.number();
        uint64 g_timestamp = c.timestamp();
        uint256 g_basefee = c.basefee();
        bytes32 g_hash = c.hash();
        uint64 g_sequenceNumber = c.sequenceNumber();
        bytes32 g_batcherHash = c.batcherHash();
        uint256 g_l1FeeOverhead = c.l1FeeOverhead();
        uint256 g_l1FeeScalar = c.l1FeeScalar();

        // The distinguishing rule:
        // If this contract's address is not the depositorAccount, then none of the stored fields should equal the corresponding inputs.
        // Conversely, if this contract's address is the depositorAccount, then stored fields may match the inputs.
        // We express this succinctly: (isDepositor) OR (all fields differ from inputs)
        address depositor = c.depositorAccount();
        bool isDepositor = (address(this) == depositor);

        bool anyMatch = (g_number == _number) || (g_timestamp == _timestamp) || (g_basefee == _basefee) || (g_hash == _hash) || (g_sequenceNumber == _sequenceNumber) || (g_batcherHash == _batcherHash) || (g_l1FeeOverhead == _l1FeeOverhead) || (g_l1FeeScalar == _l1FeeScalar);

        // On the original contract P the require enforces that only depositor can set values, so if caller != depositor then no stored field will match inputs -> anyMatch == false.
        // On mutant M the require is removed, so any caller can set values and anyMatch can be true even when caller != depositor.
        assert(isDepositor || (!anyMatch));
    }

    // allow receiving ETH if needed elsewhere (not used here)
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address that will attempt to call setL1BlockValues
    function testFuzz_property(address caller) public {
        // keep caller in wide domain but avoid zero address which is atypical
        vm.assume(caller != address(0));

        // prepare arbitrary but valid parameters for the call
        uint64 _number = 1;
        uint64 _timestamp = 1;
        uint256 _basefee = 1;
        bytes32 _hash = bytes32(uint256(1));
        uint64 _sequenceNumber = 1;
        bytes32 _batcherHash = bytes32(uint256(2));
        uint256 _l1FeeOverhead = 1;
        uint256 _l1FeeScalar = 1;

        // ensure caller has some ETH so that if call were payable it would not fail due to lack of funds
        vm.deal(caller, 1 ether);

        // try the call as the fuzzed caller, capture whether it succeeded (reference should only succeed
        // when caller == c.depositorAccount())
        bool ok;
        vm.prank(caller);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: the reference contract only allows the call when msg.sender equals the
        // runtime-stored depositorAccount. We assert that ok is equal to (caller == c.depositorAccount()).
        // This holds for all inputs on the reference implementation; the mutant that checks the hardcoded
        // DEPOSITOR_ACCOUNT instead will allow calls from that constant address even when depositorAccount
        // is different, so the fuzz should find a caller that makes this assertion fail on the mutant.
        assertTrue(ok == (caller == c.depositorAccount()));
    }
}
